"""Original notes tied to the reviewed botanical preparations and terminology."""
from pathlib import Path
import json
from datetime import date
R=Path(__file__).resolve().parents[1];O=R/'tmp/botany89'
D='https://dicciomed.usal.es/palabra/';RAE='https://dle.rae.es/'
source=lambda k:json.loads((O/(k+'.json')).read_text(encoding='utf8'))['url']
ROWS={
'floema-placas-cribosas':('El floema transporta sustancias orgánicas entre regiones de la planta. En las angiospermas, los elementos de los tubos cribosos se comunican mediante placas perforadas.',
 ['Buscar las paredes terminales con numerosos poros, vistas de frente en las micrografías electrónicas.', 'No confundirlas con una placa perforada de un vaso del xilema. El recorte óptico muestra la unión entre elementos; por sí solo es menos informativo que las vistas de los poros.', 'La calosa puede estrechar u ocluir los poros. La fotografía de bambú muestra distintos estados tras una lesión; no todos los campos representan la misma condición funcional.'],
 'Floema procede del alemán Phloëm, formado sobre el griego phloós, corteza. Criboso describe su semejanza con una criba por la presencia de poros.', ['vigo-floema','wsu-plate'],[D+'floema']),
'grano-de-almidon':('Depósito organizado de almidón, un polisacárido de reserva vegetal que se acumula dentro de plastos. Las imágenes proceden de patata.',
 ['Granos ovalados o redondeados, con tamaño y contorno variables; algunos permiten reconocer laminaciones.', 'El yodo da una coloración oscura característica. La polarización cruzada cambia su aspecto por la birrefringencia.', 'Distinguir grano y amiloplasto: el depósito no es toda la célula ni puede verse siempre la envoltura del plasto con microscopía óptica.'],
 'Almidón reúne el artículo árabe al- con una historia que pasa por el griego ámylon y las formas latinas amylum y amidum. Grano describe la forma de cada depósito.', ['wisc-potato','wisc-starch','wisc-iodine','wisc-polar'],[RAE+'almidón']),
'grano-de-polen-de-lirio':('Microgametófito de una planta con semilla. En esta ficha las fuentes identifican Lilium; una de las vistas muestra Lilium longiflorum germinando.',
 ['Granos grandes y aproximadamente ovalados, con pared externa marcada y superficie ornamentada.', 'La preparación teñida permite apreciar regiones internas; la de germinación muestra prolongaciones tubulares.', 'Lirio es un nombre común aplicado a plantas diferentes. Aquí se documenta Lilium; no se atribuye automáticamente la preparación a Iris ni a una especie de lirio sin identificar.'],
 'Polen llega del latín científico pollen y del latino pollen, pollinis, harina fina. Lirio procede del latín lilium, nombre que también se conserva en el género Lilium.', ['wisc-lily','cnrs-lily'],[RAE+'polen',RAE+'lirio']),
'grano-de-polen-de-pino':('Polen de Pinus, documentado en la colección Phycokey de la Universidad de New Hampshire.',
 ['Cuerpo central asociado a dos sacos aeríferos que producen una silueta característica.', 'Los sacos no son dos células independientes. El enfoque y la orientación cambian mucho el contorno.', 'Otras coníferas, como Picea, también tienen polen bisacado. Estos dos campos están identificados como Pinus por la fuente; la silueta aislada no determina una especie concreta de pino.'],
 'Polen procede del latino pollen, harina fina. Pino viene del latín pinus, que se conserva como nombre del género Pinus.', ['unh-pollen'],[RAE+'polen',RAE+'pino']),
'granos-de-polen':('Microgametófitos de las plantas con semilla, protegidos por una pared resistente. Las vistas incorporadas son ejemplos bisacados de Pinus y Picea.',
 ['Reconocer el cuerpo del grano, su pared y, en estos ejemplos, los sacos aeríferos.', 'El polen varía mucho en forma, ornamentación y aberturas: los dos sacos no son un rasgo de todo el polen.', 'No confundir polen con esporas de helecho ni con semillas. Esta entrada pide reconocer la estructura general.'],
 'Polen procede del latín científico pollen, tomado del latino pollen, pollinis, referido a harina fina.', ['unh-pollen','vigo-flower'],[RAE+'polen']),
'granos-de-polen-con-tubo-polinico':('Polen en germinación que emite un tubo por el que se desplazan los gametos masculinos. Las fotografías son de Lilium longiflorum y Penstemon.',
 ['Buscar la continuidad entre un grano de polen y una prolongación tubular, que puede ser mucho más larga que el grano.', 'Separar el tubo de fibras, restos de tejido o filamentos simplemente superpuestos.', 'La germinación puede observarse en medios de cultivo y sobre superficies experimentales: una imagen de tubo no demuestra por sí sola fecundación.'],
 'Polen procede del latino pollen, harina fina. Polínico significa relativo al polen; tubo describe la forma alargada de la prolongación.', ['cnrs-lily','uk-tubes'],[RAE+'polen']),
'soros-o-esporangios-de-helecho':('Los esporangios producen y contienen esporas. En muchos helechos se reúnen en grupos llamados soros, situados en la superficie o el margen de las frondes.',
 ['La vista de hoja muestra grupos repetidos de esporangios; el detalle microscópico muestra un leptosporangio con esporas y un anillo de células engrosadas.', 'Distinguir el esporangio individual del soro que lo agrupa con otros.', 'La forma de los soros y la presencia de indusio varían entre grupos. No todos los helechos tienen soros redondos ni todos los esporangios son de tipo leptosporangiado.'],
 'Soro procede del griego sōrós, montón. Esporangio llega del latín científico sporangium y combina los griegos sporá, semilla, y angeîon, vaso o recipiente.', ['unam-ferns'],[RAE+'soro',RAE+'esporangio']),
'cristales-de-oxalato':('Inclusiones cristalinas de oxalato cálcico en tejidos vegetales. Las imágenes muestran haces de ráfides y agregados llamados drusas.',
 ['Las ráfides son cristales alargados agrupados como un haz de agujas.', 'Las drusas forman agregados compactos; el contraste de la preparación puede hacerlas parecer muy oscuras.', 'No confundir un cristal o agregado con un núcleo. Una forma geométrica aislada no demuestra su composición química; aquí se conserva la identificación del atlas.'],
 'Oxalato designa una sal o éster del ácido oxálico. Oxálico se relaciona con el latín oxalis y el griego oxalís, acedera. La historia concreta de los términos ráfide y drusa queda pendiente de contraste.', ['wisc-cell-index','wisc-raphides','wisc-druses'],[RAE+'oxalato',RAE+'oxálico']),
'celula-vegetal':('Unidad celular de los vegetales. Las micrografías electrónicas permiten comparar una célula joven y otra con cloroplastos y una vacuola amplia.',
 ['Pared celular externa a la membrana, núcleo y compartimentos internos.', 'Los cloroplastos muestran un sistema de membranas internas; la vacuola ocupa una región clara delimitada.', 'No todas las células vegetales tienen cloroplastos ni una gran vacuola central. Valorar el conjunto y el estado de desarrollo, sin exigir el dibujo idealizado de un libro.'],
 'Célula procede del latín científico cellula y del latino cellula, celdilla, diminutivo de cella, celda. El adjetivo vegetal indica el ámbito biológico de esta preparación.', ['wisc-young-cell','wisc-mature-cell','vigo-cell-intro'],[RAE+'célula']),
'meristemo-en-mitosis':('Tejido vegetal con células en división. Las nuevas imágenes son detalles del ápice radicular de Allium que muestran metafase y anafase.',
 ['Cromosomas condensados en células delimitadas por paredes vegetales.', 'En metafase se agrupan en la región ecuatorial; en anafase se separan en dos grupos hacia polos opuestos.', 'En el mismo tejido también hay células en interfase. Una foto general del ápice sin figuras divisorias reconocibles no sustituye esta pregunta.'],
 'Meristemo se forma sobre el griego meristós, dividido, con una terminación tomada de floema. Mitosis combina el griego mítos, hilo, con un sufijo de proceso.', ['wisc-mitosis-valid','wisc-allium-metaphase','wisc-allium-anaphase'],[D+'meristemo',D+'mitosis']),
'saco-embrionario':('Gametófito femenino de las angiospermas, situado dentro del óvulo. No es sinónimo de embrión ni de semilla.',
 ['Región relativamente amplia dentro de la nucela del óvulo, con sus células o núcleos visibles según el plano de corte.', 'Las preparaciones de Lilium muestran distintos campos; no deben contarse ocho núcleos si el corte no los conserva todos.', 'La organización de siete células y ocho núcleos es un modelo frecuente de saco maduro, no una regla para todos los tipos de desarrollo. Las letras y el nombre impresos se excluyen del campo de estudio.'],
 'Embrionario deriva de embrión, procedente del griego émbryon. La expresión saco embrionario es una denominación histórica del gametófito femenino; no implica que la estructura fotografiada sea ya un embrión.', ['wisc-sac-plain','wisc-sac-other','vigo-flower'],[RAE+'embrión','https://amigo.geneontology.org/amigo/term/PO%3A0025074']),
'embrion-semilla':('El embrión es la planta joven originada a partir del cigoto y contenida en la semilla en desarrollo. Se diferencia del endospermo y de las cubiertas.',
 ['En la preparación de Lilium se observa el contexto del embrión y el endospermo dentro de los tejidos del óvulo.', 'No identificar como embrión toda la región interna ni el tejido nutritivo.', 'Este campo conserva contexto, pero no permite reconocer de forma inequívoca todos los órganos embrionarios. No se presenta como vista diagnóstica suficiente en Andalucía.'],
 'Embrión procede del griego émbryon. Semilla nombra la estructura que contiene al embrión; la derivación lingüística completa de semilla queda pendiente de contraste.', ['wisc-embryo','vigo-seed'],[RAE+'embrión']),
'centrosoma-centriolos-diplosoma':('El centrosoma organiza microtúbulos en muchas células animales. Incluye material pericentriolar y habitualmente una pareja de centriolos, denominada diplosoma.',
 ['Un centriolo típico presenta nueve tripletes de microtúbulos; la sección y la orientación determinan su aspecto.', 'Distinguir la pareja de centriolos del centrosoma completo, que incluye el material de alrededor.', 'Las plantas vasculares forman husos mitóticos sin centrosomas de este tipo. En este lote se completa la ficha, sin convertir un esquema molecular rotulado en una foto para adivinar.'],
 'Centrosoma combina elementos griegos de centro y cuerpo. Centriolo se forma a partir de centro con un diminutivo latino. Diplosoma reúne elementos griegos relacionados con doble y cuerpo.', ['vigo-centrioles'],[D+'centrosoma',D+'centriolo',D+'diplosoma'])
}
def main():
 p=R/'data/study-notes.json';notes=json.loads(p.read_text(encoding='utf8'));cat={x['id'] for x in json.loads((R/'data/species.json').read_text(encoding='utf8'))}
 for suffix,(description,diagnostics,etymology,keys,extra) in ROWS.items():
  id='estructura-'+suffix
  if id not in cat or id in notes:raise ValueError('Unknown or existing profile: '+id)
  urls=list(dict.fromkeys([source(k) for k in keys]+extra))
  notes[id]={'description':description,'diagnostics':diagnostics,'etymology':etymology,'sources':[{'url':u,'title':'Origen del término · fuente lingüística' if 'dle.rae' in u or 'dicciomed' in u else 'Preparación y estructura · fuente científica'} for u in urls],'reviewedAt':date.today().isoformat(),'reviewStatus':'reviewed','scope':'Síntesis propia. Las raíces pendientes se indican expresamente. Se distingue estructura, organismo de procedencia y límite de identificación del campo. No corresponde una familia taxonómica a una estructura celular o tisular.'}
 p.write_text(json.dumps(notes,ensure_ascii=False,indent=2),encoding='utf8');print(len(ROWS),'new profiles')
if __name__=='__main__':main()
